pm.test("Retorna 201 Created", function () {
    pm.response.to.have.status(201);
});

const resposta = pm.response.json();

pm.test("Peça recebeu código", function () {
    pm.expect(resposta.codigo).to.be.a("number");
});

pm.collectionVariables.set("pecaId", resposta.codigo);

pm.test("Retorna 201 Created", function () {
    pm.response.to.have.status(201);
});

const resposta = pm.response.json();

pm.test("OS possui ID, data e status", function () {
    pm.expect(resposta.id).to.be.a("number");
    pm.expect(resposta.dataAbertura).to.exist;
    pm.expect(resposta.status).to.exist;
});

pm.collectionVariables.set("ordemId", resposta.id);
pm.collectionVariables.set("ordemDataAbertura", resposta.dataAbertura);
pm.collectionVariables.set("ordemStatus", resposta.status);

pm.test("Retorna 200 OK", function () {
    pm.response.to.have.status(200);
});

const resposta = pm.response.json();

pm.test("Atualizou descrição e valor", function () {
    pm.expect(resposta.descricaoProblema)
        .to.eql("Problema atualizado pela collection");

    pm.expect(resposta.valor).to.eql(250.0);
});

pm.test("Preservou ID, data e status", function () {
    pm.expect(resposta.id)
        .to.eql(Number(pm.collectionVariables.get("ordemId")));

    pm.expect(resposta.dataAbertura)
        .to.eql(pm.collectionVariables.get("ordemDataAbertura"));

    pm.expect(resposta.status)
        .to.eql(pm.collectionVariables.get("ordemStatus"));
});

pm.test("Retorna 200 OK", function () {
    pm.response.to.have.status(200);
});

const resposta = pm.response.json();

pm.test("Alteração ficou persistida", function () {
    pm.expect(resposta.descricaoProblema)
        .to.eql("Problema atualizado pela collection");

    pm.expect(resposta.valor).to.eql(250.0);
});

pm.test("Retorna 204 No Content", function () {
    pm.response.to.have.status(204);
});

pm.test("Resposta não possui corpo", function () {
    pm.expect(pm.response.text()).to.eql("");
});

pm.test("Retorna 201 Created", function () {
    pm.response.to.have.status(201);
});

const resposta = pm.response.json();
const pecaId = Number(pm.collectionVariables.get("pecaId"));

pm.test("Pedido possui duas linhas da mesma peça", function () {
    pm.expect(resposta.itens).to.have.lengthOf(2);
    pm.expect(resposta.itens[0].codigoPeca).to.eql(pecaId);
    pm.expect(resposta.itens[1].codigoPeca).to.eql(pecaId);
});

pm.test("Quantidades estão corretas", function () {
    pm.expect(resposta.itens[0].quantidade).to.eql(1);
    pm.expect(resposta.itens[1].quantidade).to.eql(2);
});

pm.test("Preços registrados estão corretos", function () {
    pm.expect(resposta.itens[0].precoUnitario).to.eql(100.0);
    pm.expect(resposta.itens[1].precoUnitario).to.eql(100.0);
});

pm.test("Valor total é 300", function () {
    pm.expect(resposta.valorTotal).to.eql(300.0);
});

pm.collectionVariables.set("pedidoId", resposta.id);

pm.test("Retorna 200 OK", function () {
    pm.response.to.have.status(200);
});

const resposta = pm.response.json();

pm.test("Pedido continua com dois itens", function () {
    pm.expect(resposta.itens).to.have.lengthOf(2);
});

pm.test("Valor total continua igual a 300", function () {
    pm.expect(resposta.valorTotal).to.eql(300.0);
});

pm.test("Retorna 204 No Content", function () {
    pm.response.to.have.status(204);
});

pm.test("Resposta não possui corpo", function () {
    pm.expect(pm.response.text()).to.eql("");
});

pm.test("Peça de apoio foi removida", function () {
    pm.response.to.have.status(204);
});
